const { contextBridge } = require("electron");

const getArgument = (prefix) =>
  process.argv
    .find((argument) => argument.startsWith(prefix))
    ?.slice(prefix.length);

contextBridge.exposeInMainWorld("desktop", {
  isElectron: true,
  apiBaseUrl: getArgument("--api-base-url=") || "http://127.0.0.1:5000",
  localApiToken: getArgument("--local-api-token=") || "",
});
